-- The inbox reads a bounded number of rows on a large workspace. inbox_entries holds one row per inbox
-- conversation (one with a message or a note that is not merged away: exactly inbox-visible.ts), with the
-- inbox's sort key, the flags its views filter on, the ticket columns a filter or sort may name and its tags,
-- so a page walks an index in order and stops after its rows; hidden widget drafts are never read.
-- inbox_tallies counts those entries by workspace, group, assignee and flags; inbox_field_tallies also by
-- priority, status category, channel and status; inbox_tag_tallies by tag as well, so the views' totals, the
-- counts' standard numbers and a filter over those fields and a tag read a handful of rows. inbox_unread holds each member's unread entries, so the
-- unread view and count read one row per unread conversation. Every value is derived: the migration fills
-- them, and triggers on every table they derive from keep them current (imports write rows with plain
-- INSERTs, so write-path code could not). A restore rebuilds them from the restored rows.
-- sort_at: coalesce(created_at of the last message, updated_at), the inbox order. unresolved: resolved_at IS
-- NULL (the list); counts_open: COALESCE(resolved_at,0)=0 (the counts). ai: an AI row with an ai_id (the list
-- and the counts' human numbers); ai_profile: an AI row whose profile exists (the counts' AI number).
-- company_id: the contact's company in the workspace. contact_revision: the highest revision of a contact
-- message that was not imported (unread for a member when above the member's read revision). tags_key: the
-- ticket's tag ids in tag order, exactly the tags field of tickets/filters.ts (its own links in the workspace).
-- The snooze probe (inbox, counts, presentation) reads one conversation's schedules, not every pending one.
CREATE INDEX workflow_schedules_conversation ON workflow_schedules(conversation_id,kind,state);
-- The ticket panel's contact picker pages contacts by name: its page walks this order instead of sorting them all.
CREATE INDEX contacts_name_order ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE,id);
CREATE TABLE inbox_entries(conversation_id TEXT NOT NULL,project_id TEXT NOT NULL,contact_id TEXT,company_id TEXT,assigned_to TEXT,group_id TEXT,status_category TEXT,priority TEXT,channel TEXT,status_id TEXT,subject TEXT,brand_id TEXT,requester_id TEXT,submitter_id TEXT,submitter_type TEXT,created_at INTEGER,updated_at INTEGER,ticket_version INTEGER,sort_at INTEGER,unresolved INTEGER NOT NULL,counts_open INTEGER NOT NULL,ai INTEGER NOT NULL,ai_profile INTEGER NOT NULL,snoozed INTEGER NOT NULL,contact_revision INTEGER,tags_key TEXT);
-- One entry per conversation; a join from a tag link or an unread row looks its entry up by this index.
CREATE UNIQUE INDEX inbox_entries_conversation ON inbox_entries(conversation_id);
-- Each index leads with the workspace and what a request pins, then the order its page walks.
CREATE INDEX inbox_entries_order ON inbox_entries(project_id,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_flags ON inbox_entries(project_id,ai,snoozed,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_assignee ON inbox_entries(project_id,assigned_to,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_company ON inbox_entries(project_id,company_id,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_contact ON inbox_entries(project_id,contact_id);
CREATE INDEX inbox_entries_status ON inbox_entries(project_id,status_category,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_priority ON inbox_entries(project_id,priority,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_entries_channel ON inbox_entries(project_id,channel,sort_at DESC,conversation_id DESC);
-- A custom sort by one ticket column (tickets/filters.ts) walks that column's index in the sort's own expression
-- (tickets/sort.ts) and order, then the newest conversation id first, and stops after its page.
CREATE INDEX inbox_entries_by_id_asc ON inbox_entries(project_id,conversation_id);
CREATE INDEX inbox_entries_by_id_desc ON inbox_entries(project_id,conversation_id DESC);
CREATE INDEX inbox_entries_by_status_id_asc ON inbox_entries(project_id,status_id,conversation_id DESC);
CREATE INDEX inbox_entries_by_status_id_desc ON inbox_entries(project_id,status_id DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_status_category_asc ON inbox_entries(project_id,CASE status_category WHEN 'new' THEN 0 WHEN 'open' THEN 1 WHEN 'pending' THEN 2 WHEN 'on_hold' THEN 3 WHEN 'solved' THEN 4 WHEN 'closed' THEN 5 END,conversation_id DESC);
CREATE INDEX inbox_entries_by_status_category_desc ON inbox_entries(project_id,CASE status_category WHEN 'new' THEN 0 WHEN 'open' THEN 1 WHEN 'pending' THEN 2 WHEN 'on_hold' THEN 3 WHEN 'solved' THEN 4 WHEN 'closed' THEN 5 END DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_priority_asc ON inbox_entries(project_id,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END,conversation_id DESC);
CREATE INDEX inbox_entries_by_priority_desc ON inbox_entries(project_id,CASE priority WHEN 'low' THEN 0 WHEN 'normal' THEN 1 WHEN 'high' THEN 2 WHEN 'urgent' THEN 3 END DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_assigned_to_asc ON inbox_entries(project_id,assigned_to,conversation_id DESC);
CREATE INDEX inbox_entries_by_assigned_to_desc ON inbox_entries(project_id,assigned_to DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_subject_asc ON inbox_entries(project_id,subject,conversation_id DESC);
CREATE INDEX inbox_entries_by_subject_desc ON inbox_entries(project_id,subject DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_channel_asc ON inbox_entries(project_id,channel,conversation_id DESC);
CREATE INDEX inbox_entries_by_channel_desc ON inbox_entries(project_id,channel DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_brand_id_asc ON inbox_entries(project_id,brand_id,conversation_id DESC);
CREATE INDEX inbox_entries_by_brand_id_desc ON inbox_entries(project_id,brand_id DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_group_id_asc ON inbox_entries(project_id,group_id,conversation_id DESC);
CREATE INDEX inbox_entries_by_group_id_desc ON inbox_entries(project_id,group_id DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_requester_id_asc ON inbox_entries(project_id,requester_id,conversation_id DESC);
CREATE INDEX inbox_entries_by_requester_id_desc ON inbox_entries(project_id,requester_id DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_submitter_id_asc ON inbox_entries(project_id,submitter_id,conversation_id DESC);
CREATE INDEX inbox_entries_by_submitter_id_desc ON inbox_entries(project_id,submitter_id DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_submitter_type_asc ON inbox_entries(project_id,submitter_type,conversation_id DESC);
CREATE INDEX inbox_entries_by_submitter_type_desc ON inbox_entries(project_id,submitter_type DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_created_at_asc ON inbox_entries(project_id,CAST(created_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_by_created_at_desc ON inbox_entries(project_id,CAST(created_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_updated_at_asc ON inbox_entries(project_id,CAST(updated_at AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_by_updated_at_desc ON inbox_entries(project_id,CAST(updated_at AS REAL) DESC,conversation_id DESC);
CREATE INDEX inbox_entries_by_ticket_version_asc ON inbox_entries(project_id,CAST(ticket_version AS REAL),conversation_id DESC);
CREATE INDEX inbox_entries_by_ticket_version_desc ON inbox_entries(project_id,CAST(ticket_version AS REAL) DESC,conversation_id DESC);
-- tags_key: the ticket's tag ids as the tags filter and sort read them (tickets/filters.ts), so a tags condition
-- reads the entry alone and a sort led by tags walks its own index.
CREATE INDEX inbox_entries_by_tags_asc ON inbox_entries(project_id,tags_key,conversation_id DESC);
CREATE INDEX inbox_entries_by_tags_desc ON inbox_entries(project_id,tags_key DESC,conversation_id DESC);
CREATE TABLE inbox_tallies(project_id TEXT NOT NULL,group_id TEXT,assigned_to TEXT,unresolved INTEGER NOT NULL,counts_open INTEGER NOT NULL,ai INTEGER NOT NULL,ai_profile INTEGER NOT NULL,snoozed INTEGER NOT NULL,total INTEGER NOT NULL);
CREATE INDEX inbox_tallies_key ON inbox_tallies(project_id,unresolved,ai,snoozed,assigned_to,group_id,counts_open,ai_profile);
CREATE TABLE inbox_tag_tallies(tag_id TEXT NOT NULL,project_id TEXT NOT NULL,group_id TEXT,assigned_to TEXT,unresolved INTEGER NOT NULL,counts_open INTEGER NOT NULL,ai INTEGER NOT NULL,ai_profile INTEGER NOT NULL,snoozed INTEGER NOT NULL,priority TEXT,status_category TEXT,channel TEXT,status_id TEXT,total INTEGER NOT NULL);
CREATE INDEX inbox_tag_tallies_key ON inbox_tag_tallies(project_id,tag_id,unresolved,ai,snoozed,priority,status_category,channel,status_id,assigned_to,group_id,counts_open,ai_profile);
CREATE TABLE inbox_field_tallies(project_id TEXT NOT NULL,group_id TEXT,assigned_to TEXT,unresolved INTEGER NOT NULL,counts_open INTEGER NOT NULL,ai INTEGER NOT NULL,ai_profile INTEGER NOT NULL,snoozed INTEGER NOT NULL,priority TEXT,status_category TEXT,channel TEXT,status_id TEXT,total INTEGER NOT NULL);
CREATE INDEX inbox_field_tallies_key ON inbox_field_tallies(project_id,unresolved,ai,snoozed,priority,status_category,channel,status_id,assigned_to,group_id);
CREATE TABLE inbox_unread(user_id TEXT NOT NULL,conversation_id TEXT NOT NULL,project_id TEXT NOT NULL,group_id TEXT,assigned_to TEXT,sort_at INTEGER,unresolved INTEGER NOT NULL,counts_open INTEGER NOT NULL,ai INTEGER NOT NULL,snoozed INTEGER NOT NULL,PRIMARY KEY(conversation_id,user_id));
CREATE INDEX inbox_unread_view ON inbox_unread(user_id,project_id,unresolved,ai,snoozed,sort_at DESC,conversation_id DESC);
CREATE INDEX inbox_unread_counts ON inbox_unread(user_id,project_id,counts_open);
INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT c.id,c.project_id,c.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=c.project_id AND cc.contact_id=c.contact_id),c.assigned_to,c.group_id,c.status_category,c.priority,c.channel,c.status_id,c.subject,c.brand_id,c.requester_id,c.submitter_id,c.submitter_type,c.created_at,c.updated_at,c.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=c.last_message_id),c.updated_at),c.resolved_at IS NULL,COALESCE(c.resolved_at,0)=0,EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=c.id AND ca.ai_id IS NOT NULL),EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=c.id),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=c.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=c.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=c.project_id AND ct.conversation_id=c.id) FROM conversations c WHERE (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=c.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=c.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=c.project_id AND merged.source_id=c.id AND merged.undone_at IS NULL);
INSERT INTO inbox_tallies(project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,total) SELECT project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,count(*) FROM inbox_entries GROUP BY project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed;
INSERT INTO inbox_tag_tallies(tag_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,total) SELECT ct.tag_id,e.project_id,e.group_id,e.assigned_to,e.unresolved,e.counts_open,e.ai,e.ai_profile,e.snoozed,e.priority,e.status_category,e.channel,e.status_id,count(*) FROM inbox_entries e JOIN conversation_tags ct ON ct.conversation_id=e.conversation_id AND ct.project_id=e.project_id GROUP BY ct.tag_id,e.project_id,e.group_id,e.assigned_to,e.unresolved,e.counts_open,e.ai,e.ai_profile,e.snoozed,e.priority,e.status_category,e.channel,e.status_id;
INSERT INTO inbox_field_tallies(project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,total) SELECT project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,count(*) FROM inbox_entries GROUP BY project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id;
INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT m.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e JOIN memberships m ON m.project_id=e.project_id WHERE e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=m.user_id),0);
CREATE TRIGGER inbox_entry_added AFTER INSERT ON inbox_entries BEGIN
 INSERT INTO inbox_tallies(project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,total) SELECT NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.ai_profile,NEW.snoozed,0 WHERE NOT EXISTS(SELECT 1 FROM inbox_tallies WHERE inbox_tallies.project_id=NEW.project_id AND inbox_tallies.group_id IS NEW.group_id AND inbox_tallies.assigned_to IS NEW.assigned_to AND inbox_tallies.unresolved=NEW.unresolved AND inbox_tallies.counts_open=NEW.counts_open AND inbox_tallies.ai=NEW.ai AND inbox_tallies.ai_profile=NEW.ai_profile AND inbox_tallies.snoozed=NEW.snoozed);
 UPDATE inbox_tallies SET total=total+1 WHERE inbox_tallies.project_id=NEW.project_id AND inbox_tallies.group_id IS NEW.group_id AND inbox_tallies.assigned_to IS NEW.assigned_to AND inbox_tallies.unresolved=NEW.unresolved AND inbox_tallies.counts_open=NEW.counts_open AND inbox_tallies.ai=NEW.ai AND inbox_tallies.ai_profile=NEW.ai_profile AND inbox_tallies.snoozed=NEW.snoozed;
 INSERT INTO inbox_tag_tallies(tag_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,total) SELECT ct.tag_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.ai_profile,NEW.snoozed,NEW.priority,NEW.status_category,NEW.channel,NEW.status_id,0 FROM conversation_tags ct WHERE ct.conversation_id=NEW.conversation_id AND ct.project_id=NEW.project_id AND NOT EXISTS(SELECT 1 FROM inbox_tag_tallies WHERE inbox_tag_tallies.tag_id=ct.tag_id AND inbox_tag_tallies.project_id=NEW.project_id AND inbox_tag_tallies.group_id IS NEW.group_id AND inbox_tag_tallies.assigned_to IS NEW.assigned_to AND inbox_tag_tallies.unresolved=NEW.unresolved AND inbox_tag_tallies.counts_open=NEW.counts_open AND inbox_tag_tallies.ai=NEW.ai AND inbox_tag_tallies.ai_profile=NEW.ai_profile AND inbox_tag_tallies.snoozed=NEW.snoozed AND inbox_tag_tallies.priority IS NEW.priority AND inbox_tag_tallies.status_category IS NEW.status_category AND inbox_tag_tallies.channel IS NEW.channel AND inbox_tag_tallies.status_id IS NEW.status_id);
 UPDATE inbox_tag_tallies SET total=total+1 WHERE tag_id IN (SELECT ct.tag_id FROM conversation_tags ct WHERE ct.conversation_id=NEW.conversation_id AND ct.project_id=NEW.project_id) AND inbox_tag_tallies.project_id=NEW.project_id AND inbox_tag_tallies.group_id IS NEW.group_id AND inbox_tag_tallies.assigned_to IS NEW.assigned_to AND inbox_tag_tallies.unresolved=NEW.unresolved AND inbox_tag_tallies.counts_open=NEW.counts_open AND inbox_tag_tallies.ai=NEW.ai AND inbox_tag_tallies.ai_profile=NEW.ai_profile AND inbox_tag_tallies.snoozed=NEW.snoozed AND inbox_tag_tallies.priority IS NEW.priority AND inbox_tag_tallies.status_category IS NEW.status_category AND inbox_tag_tallies.channel IS NEW.channel AND inbox_tag_tallies.status_id IS NEW.status_id;
 INSERT INTO inbox_field_tallies(project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,total) SELECT NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.ai_profile,NEW.snoozed,NEW.priority,NEW.status_category,NEW.channel,NEW.status_id,0 WHERE NOT EXISTS(SELECT 1 FROM inbox_field_tallies WHERE inbox_field_tallies.project_id=NEW.project_id AND inbox_field_tallies.group_id IS NEW.group_id AND inbox_field_tallies.assigned_to IS NEW.assigned_to AND inbox_field_tallies.unresolved=NEW.unresolved AND inbox_field_tallies.counts_open=NEW.counts_open AND inbox_field_tallies.ai=NEW.ai AND inbox_field_tallies.ai_profile=NEW.ai_profile AND inbox_field_tallies.snoozed=NEW.snoozed AND inbox_field_tallies.priority IS NEW.priority AND inbox_field_tallies.status_category IS NEW.status_category AND inbox_field_tallies.channel IS NEW.channel AND inbox_field_tallies.status_id IS NEW.status_id);
 UPDATE inbox_field_tallies SET total=total+1 WHERE inbox_field_tallies.project_id=NEW.project_id AND inbox_field_tallies.group_id IS NEW.group_id AND inbox_field_tallies.assigned_to IS NEW.assigned_to AND inbox_field_tallies.unresolved=NEW.unresolved AND inbox_field_tallies.counts_open=NEW.counts_open AND inbox_field_tallies.ai=NEW.ai AND inbox_field_tallies.ai_profile=NEW.ai_profile AND inbox_field_tallies.snoozed=NEW.snoozed AND inbox_field_tallies.priority IS NEW.priority AND inbox_field_tallies.status_category IS NEW.status_category AND inbox_field_tallies.channel IS NEW.channel AND inbox_field_tallies.status_id IS NEW.status_id;
 DELETE FROM inbox_unread WHERE conversation_id=NEW.conversation_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT m.user_id,NEW.conversation_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.sort_at,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.snoozed FROM memberships m WHERE m.project_id=NEW.project_id AND NEW.contact_revision IS NOT NULL AND NEW.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=NEW.conversation_id AND r.user_id=m.user_id),0);
END;
CREATE TRIGGER inbox_entry_removed AFTER DELETE ON inbox_entries BEGIN
 UPDATE inbox_tallies SET total=total-1 WHERE inbox_tallies.project_id=OLD.project_id AND inbox_tallies.group_id IS OLD.group_id AND inbox_tallies.assigned_to IS OLD.assigned_to AND inbox_tallies.unresolved=OLD.unresolved AND inbox_tallies.counts_open=OLD.counts_open AND inbox_tallies.ai=OLD.ai AND inbox_tallies.ai_profile=OLD.ai_profile AND inbox_tallies.snoozed=OLD.snoozed;
 DELETE FROM inbox_tallies WHERE total=0 AND inbox_tallies.project_id=OLD.project_id AND inbox_tallies.group_id IS OLD.group_id AND inbox_tallies.assigned_to IS OLD.assigned_to AND inbox_tallies.unresolved=OLD.unresolved AND inbox_tallies.counts_open=OLD.counts_open AND inbox_tallies.ai=OLD.ai AND inbox_tallies.ai_profile=OLD.ai_profile AND inbox_tallies.snoozed=OLD.snoozed;
 UPDATE inbox_tag_tallies SET total=total-1 WHERE tag_id IN (SELECT ct.tag_id FROM conversation_tags ct WHERE ct.conversation_id=OLD.conversation_id AND ct.project_id=OLD.project_id) AND inbox_tag_tallies.project_id=OLD.project_id AND inbox_tag_tallies.group_id IS OLD.group_id AND inbox_tag_tallies.assigned_to IS OLD.assigned_to AND inbox_tag_tallies.unresolved=OLD.unresolved AND inbox_tag_tallies.counts_open=OLD.counts_open AND inbox_tag_tallies.ai=OLD.ai AND inbox_tag_tallies.ai_profile=OLD.ai_profile AND inbox_tag_tallies.snoozed=OLD.snoozed AND inbox_tag_tallies.priority IS OLD.priority AND inbox_tag_tallies.status_category IS OLD.status_category AND inbox_tag_tallies.channel IS OLD.channel AND inbox_tag_tallies.status_id IS OLD.status_id;
 DELETE FROM inbox_tag_tallies WHERE total=0 AND tag_id IN (SELECT ct.tag_id FROM conversation_tags ct WHERE ct.conversation_id=OLD.conversation_id AND ct.project_id=OLD.project_id) AND inbox_tag_tallies.project_id=OLD.project_id AND inbox_tag_tallies.group_id IS OLD.group_id AND inbox_tag_tallies.assigned_to IS OLD.assigned_to AND inbox_tag_tallies.unresolved=OLD.unresolved AND inbox_tag_tallies.counts_open=OLD.counts_open AND inbox_tag_tallies.ai=OLD.ai AND inbox_tag_tallies.ai_profile=OLD.ai_profile AND inbox_tag_tallies.snoozed=OLD.snoozed AND inbox_tag_tallies.priority IS OLD.priority AND inbox_tag_tallies.status_category IS OLD.status_category AND inbox_tag_tallies.channel IS OLD.channel AND inbox_tag_tallies.status_id IS OLD.status_id;
 UPDATE inbox_field_tallies SET total=total-1 WHERE inbox_field_tallies.project_id=OLD.project_id AND inbox_field_tallies.group_id IS OLD.group_id AND inbox_field_tallies.assigned_to IS OLD.assigned_to AND inbox_field_tallies.unresolved=OLD.unresolved AND inbox_field_tallies.counts_open=OLD.counts_open AND inbox_field_tallies.ai=OLD.ai AND inbox_field_tallies.ai_profile=OLD.ai_profile AND inbox_field_tallies.snoozed=OLD.snoozed AND inbox_field_tallies.priority IS OLD.priority AND inbox_field_tallies.status_category IS OLD.status_category AND inbox_field_tallies.channel IS OLD.channel AND inbox_field_tallies.status_id IS OLD.status_id;
 DELETE FROM inbox_field_tallies WHERE total=0 AND inbox_field_tallies.project_id=OLD.project_id AND inbox_field_tallies.group_id IS OLD.group_id AND inbox_field_tallies.assigned_to IS OLD.assigned_to AND inbox_field_tallies.unresolved=OLD.unresolved AND inbox_field_tallies.counts_open=OLD.counts_open AND inbox_field_tallies.ai=OLD.ai AND inbox_field_tallies.ai_profile=OLD.ai_profile AND inbox_field_tallies.snoozed=OLD.snoozed AND inbox_field_tallies.priority IS OLD.priority AND inbox_field_tallies.status_category IS OLD.status_category AND inbox_field_tallies.channel IS OLD.channel AND inbox_field_tallies.status_id IS OLD.status_id;
 DELETE FROM inbox_unread WHERE conversation_id=OLD.conversation_id;
END;
-- A reply moves an entry in the inbox order and may make it unread; its flags and tallies stay.
CREATE TRIGGER inbox_entry_reordered AFTER UPDATE OF sort_at,contact_revision ON inbox_entries WHEN NEW.sort_at IS NOT OLD.sort_at OR NEW.contact_revision IS NOT OLD.contact_revision BEGIN
 DELETE FROM inbox_unread WHERE conversation_id=NEW.conversation_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT m.user_id,NEW.conversation_id,NEW.project_id,NEW.group_id,NEW.assigned_to,NEW.sort_at,NEW.unresolved,NEW.counts_open,NEW.ai,NEW.snoozed FROM memberships m WHERE m.project_id=NEW.project_id AND NEW.contact_revision IS NOT NULL AND NEW.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=NEW.conversation_id AND r.user_id=m.user_id),0);
END;
CREATE TRIGGER inbox_read_added AFTER INSERT ON conversation_reads BEGIN
 DELETE FROM inbox_unread WHERE conversation_id=NEW.conversation_id AND user_id=NEW.user_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT NEW.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e WHERE e.conversation_id=NEW.conversation_id AND EXISTS(SELECT 1 FROM memberships m WHERE m.project_id=e.project_id AND m.user_id=NEW.user_id) AND e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=NEW.user_id),0);
END;
CREATE TRIGGER inbox_read_changed AFTER UPDATE ON conversation_reads BEGIN
 DELETE FROM inbox_unread WHERE conversation_id=OLD.conversation_id AND user_id=OLD.user_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT OLD.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e WHERE e.conversation_id=OLD.conversation_id AND EXISTS(SELECT 1 FROM memberships m WHERE m.project_id=e.project_id AND m.user_id=OLD.user_id) AND e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=OLD.user_id),0);
 DELETE FROM inbox_unread WHERE conversation_id=NEW.conversation_id AND user_id=NEW.user_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT NEW.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e WHERE e.conversation_id=NEW.conversation_id AND EXISTS(SELECT 1 FROM memberships m WHERE m.project_id=e.project_id AND m.user_id=NEW.user_id) AND e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=NEW.user_id),0);
END;
CREATE TRIGGER inbox_read_removed AFTER DELETE ON conversation_reads BEGIN
 DELETE FROM inbox_unread WHERE conversation_id=OLD.conversation_id AND user_id=OLD.user_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT OLD.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e WHERE e.conversation_id=OLD.conversation_id AND EXISTS(SELECT 1 FROM memberships m WHERE m.project_id=e.project_id AND m.user_id=OLD.user_id) AND e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=OLD.user_id),0);
END;
CREATE TRIGGER inbox_member_added AFTER INSERT ON memberships BEGIN
 DELETE FROM inbox_unread WHERE user_id=NEW.user_id AND project_id=NEW.project_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT NEW.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e WHERE e.project_id=NEW.project_id AND e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=NEW.user_id),0);
END;
CREATE TRIGGER inbox_member_moved AFTER UPDATE OF project_id,user_id ON memberships BEGIN
 DELETE FROM inbox_unread WHERE user_id=OLD.user_id AND project_id=OLD.project_id;
 DELETE FROM inbox_unread WHERE user_id=NEW.user_id AND project_id=NEW.project_id;
 INSERT INTO inbox_unread(user_id,conversation_id,project_id,group_id,assigned_to,sort_at,unresolved,counts_open,ai,snoozed) SELECT NEW.user_id,e.conversation_id,e.project_id,e.group_id,e.assigned_to,e.sort_at,e.unresolved,e.counts_open,e.ai,e.snoozed FROM inbox_entries e WHERE e.project_id=NEW.project_id AND e.contact_revision IS NOT NULL AND e.contact_revision>coalesce((SELECT r.revision FROM conversation_reads r WHERE r.conversation_id=e.conversation_id AND r.user_id=NEW.user_id),0);
END;
CREATE TRIGGER inbox_member_removed AFTER DELETE ON memberships BEGIN
 DELETE FROM inbox_unread WHERE user_id=OLD.user_id AND project_id=OLD.project_id;
END;
CREATE TRIGGER inbox_tag_linked AFTER INSERT ON conversation_tags BEGIN
 INSERT INTO inbox_tag_tallies(tag_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,total) SELECT NEW.tag_id,e.project_id,e.group_id,e.assigned_to,e.unresolved,e.counts_open,e.ai,e.ai_profile,e.snoozed,e.priority,e.status_category,e.channel,e.status_id,0 FROM inbox_entries e WHERE e.conversation_id=NEW.conversation_id AND e.project_id=NEW.project_id AND NOT EXISTS(SELECT 1 FROM inbox_tag_tallies WHERE inbox_tag_tallies.tag_id=NEW.tag_id AND inbox_tag_tallies.project_id=e.project_id AND inbox_tag_tallies.group_id IS e.group_id AND inbox_tag_tallies.assigned_to IS e.assigned_to AND inbox_tag_tallies.unresolved=e.unresolved AND inbox_tag_tallies.counts_open=e.counts_open AND inbox_tag_tallies.ai=e.ai AND inbox_tag_tallies.ai_profile=e.ai_profile AND inbox_tag_tallies.snoozed=e.snoozed AND inbox_tag_tallies.priority IS e.priority AND inbox_tag_tallies.status_category IS e.status_category AND inbox_tag_tallies.channel IS e.channel AND inbox_tag_tallies.status_id IS e.status_id);
 UPDATE inbox_tag_tallies SET total=total+1 WHERE project_id=NEW.project_id AND tag_id=NEW.tag_id AND EXISTS(SELECT 1 FROM inbox_entries e WHERE e.conversation_id=NEW.conversation_id AND e.project_id=NEW.project_id AND e.project_id=inbox_tag_tallies.project_id AND e.group_id IS inbox_tag_tallies.group_id AND e.assigned_to IS inbox_tag_tallies.assigned_to AND e.unresolved=inbox_tag_tallies.unresolved AND e.counts_open=inbox_tag_tallies.counts_open AND e.ai=inbox_tag_tallies.ai AND e.ai_profile=inbox_tag_tallies.ai_profile AND e.snoozed=inbox_tag_tallies.snoozed AND e.priority IS inbox_tag_tallies.priority AND e.status_category IS inbox_tag_tallies.status_category AND e.channel IS inbox_tag_tallies.channel AND e.status_id IS inbox_tag_tallies.status_id);
 UPDATE inbox_entries SET tags_key=(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=inbox_entries.project_id AND ct.conversation_id=inbox_entries.conversation_id) WHERE conversation_id IN (NEW.conversation_id);
END;
CREATE TRIGGER inbox_tag_unlinked AFTER DELETE ON conversation_tags BEGIN
 UPDATE inbox_tag_tallies SET total=total-1 WHERE project_id=OLD.project_id AND tag_id=OLD.tag_id AND EXISTS(SELECT 1 FROM inbox_entries e WHERE e.conversation_id=OLD.conversation_id AND e.project_id=OLD.project_id AND e.project_id=inbox_tag_tallies.project_id AND e.group_id IS inbox_tag_tallies.group_id AND e.assigned_to IS inbox_tag_tallies.assigned_to AND e.unresolved=inbox_tag_tallies.unresolved AND e.counts_open=inbox_tag_tallies.counts_open AND e.ai=inbox_tag_tallies.ai AND e.ai_profile=inbox_tag_tallies.ai_profile AND e.snoozed=inbox_tag_tallies.snoozed AND e.priority IS inbox_tag_tallies.priority AND e.status_category IS inbox_tag_tallies.status_category AND e.channel IS inbox_tag_tallies.channel AND e.status_id IS inbox_tag_tallies.status_id);
 DELETE FROM inbox_tag_tallies WHERE project_id=OLD.project_id AND tag_id=OLD.tag_id AND total=0;
 UPDATE inbox_entries SET tags_key=(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=inbox_entries.project_id AND ct.conversation_id=inbox_entries.conversation_id) WHERE conversation_id IN (OLD.conversation_id);
END;
CREATE TRIGGER inbox_tag_relinked AFTER UPDATE OF project_id,conversation_id,tag_id ON conversation_tags BEGIN
 UPDATE inbox_tag_tallies SET total=total-1 WHERE project_id=OLD.project_id AND tag_id=OLD.tag_id AND EXISTS(SELECT 1 FROM inbox_entries e WHERE e.conversation_id=OLD.conversation_id AND e.project_id=OLD.project_id AND e.project_id=inbox_tag_tallies.project_id AND e.group_id IS inbox_tag_tallies.group_id AND e.assigned_to IS inbox_tag_tallies.assigned_to AND e.unresolved=inbox_tag_tallies.unresolved AND e.counts_open=inbox_tag_tallies.counts_open AND e.ai=inbox_tag_tallies.ai AND e.ai_profile=inbox_tag_tallies.ai_profile AND e.snoozed=inbox_tag_tallies.snoozed AND e.priority IS inbox_tag_tallies.priority AND e.status_category IS inbox_tag_tallies.status_category AND e.channel IS inbox_tag_tallies.channel AND e.status_id IS inbox_tag_tallies.status_id);
 DELETE FROM inbox_tag_tallies WHERE project_id=OLD.project_id AND tag_id=OLD.tag_id AND total=0;
 INSERT INTO inbox_tag_tallies(tag_id,project_id,group_id,assigned_to,unresolved,counts_open,ai,ai_profile,snoozed,priority,status_category,channel,status_id,total) SELECT NEW.tag_id,e.project_id,e.group_id,e.assigned_to,e.unresolved,e.counts_open,e.ai,e.ai_profile,e.snoozed,e.priority,e.status_category,e.channel,e.status_id,0 FROM inbox_entries e WHERE e.conversation_id=NEW.conversation_id AND e.project_id=NEW.project_id AND NOT EXISTS(SELECT 1 FROM inbox_tag_tallies WHERE inbox_tag_tallies.tag_id=NEW.tag_id AND inbox_tag_tallies.project_id=e.project_id AND inbox_tag_tallies.group_id IS e.group_id AND inbox_tag_tallies.assigned_to IS e.assigned_to AND inbox_tag_tallies.unresolved=e.unresolved AND inbox_tag_tallies.counts_open=e.counts_open AND inbox_tag_tallies.ai=e.ai AND inbox_tag_tallies.ai_profile=e.ai_profile AND inbox_tag_tallies.snoozed=e.snoozed AND inbox_tag_tallies.priority IS e.priority AND inbox_tag_tallies.status_category IS e.status_category AND inbox_tag_tallies.channel IS e.channel AND inbox_tag_tallies.status_id IS e.status_id);
 UPDATE inbox_tag_tallies SET total=total+1 WHERE project_id=NEW.project_id AND tag_id=NEW.tag_id AND EXISTS(SELECT 1 FROM inbox_entries e WHERE e.conversation_id=NEW.conversation_id AND e.project_id=NEW.project_id AND e.project_id=inbox_tag_tallies.project_id AND e.group_id IS inbox_tag_tallies.group_id AND e.assigned_to IS inbox_tag_tallies.assigned_to AND e.unresolved=inbox_tag_tallies.unresolved AND e.counts_open=inbox_tag_tallies.counts_open AND e.ai=inbox_tag_tallies.ai AND e.ai_profile=inbox_tag_tallies.ai_profile AND e.snoozed=inbox_tag_tallies.snoozed AND e.priority IS inbox_tag_tallies.priority AND e.status_category IS inbox_tag_tallies.status_category AND e.channel IS inbox_tag_tallies.channel AND e.status_id IS inbox_tag_tallies.status_id);
 UPDATE inbox_entries SET tags_key=(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=inbox_entries.project_id AND ct.conversation_id=inbox_entries.conversation_id) WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id);
END;
-- A contact's company follows its link; the entries of its conversations carry it.
CREATE TRIGGER inbox_company_linked AFTER INSERT ON contact_companies BEGIN
 UPDATE inbox_entries SET company_id=NEW.company_id WHERE project_id=NEW.project_id AND contact_id=NEW.contact_id;
END;
CREATE TRIGGER inbox_company_relinked AFTER UPDATE OF project_id,contact_id,company_id ON contact_companies BEGIN
 UPDATE inbox_entries SET company_id=NULL WHERE project_id=OLD.project_id AND contact_id=OLD.contact_id;
 UPDATE inbox_entries SET company_id=NEW.company_id WHERE project_id=NEW.project_id AND contact_id=NEW.contact_id;
END;
CREATE TRIGGER inbox_company_unlinked AFTER DELETE ON contact_companies BEGIN
 UPDATE inbox_entries SET company_id=NULL WHERE project_id=OLD.project_id AND contact_id=OLD.contact_id;
END;
CREATE TRIGGER inbox_conversation_added AFTER INSERT ON conversations BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=NEW.id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL),EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=NEW.id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
CREATE TRIGGER inbox_conversation_changed AFTER UPDATE OF id,project_id,contact_id,assigned_to,group_id,resolved_at,status_category,priority,channel,status_id ON conversations WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.contact_id IS NOT OLD.contact_id OR NEW.assigned_to IS NOT OLD.assigned_to OR NEW.group_id IS NOT OLD.group_id OR NEW.resolved_at IS NOT OLD.resolved_at OR NEW.status_category IS NOT OLD.status_category OR NEW.priority IS NOT OLD.priority OR NEW.channel IS NOT OLD.channel OR NEW.status_id IS NOT OLD.status_id BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=OLD.id;
 DELETE FROM inbox_entries WHERE conversation_id=NEW.id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL),EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=NEW.id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
-- A reply moves the conversation in the inbox order, and a ticket edit changes the columns a filter or sort
-- names; its flags and tallies stay.
CREATE TRIGGER inbox_conversation_detailed AFTER UPDATE OF last_message_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version ON conversations WHEN NEW.last_message_id IS NOT OLD.last_message_id OR NEW.subject IS NOT OLD.subject OR NEW.brand_id IS NOT OLD.brand_id OR NEW.requester_id IS NOT OLD.requester_id OR NEW.submitter_id IS NOT OLD.submitter_id OR NEW.submitter_type IS NOT OLD.submitter_type OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at OR NEW.ticket_version IS NOT OLD.ticket_version BEGIN
 UPDATE inbox_entries SET sort_at=coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=NEW.last_message_id),NEW.updated_at),subject=NEW.subject,brand_id=NEW.brand_id,requester_id=NEW.requester_id,submitter_id=NEW.submitter_id,submitter_type=NEW.submitter_type,created_at=NEW.created_at,updated_at=NEW.updated_at,ticket_version=NEW.ticket_version WHERE conversation_id=NEW.id;
END;
CREATE TRIGGER inbox_conversation_removed AFTER DELETE ON conversations BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=OLD.id;
END;
-- A first message (or note) brings a conversation into the inbox; a later one changes only its unread revision and order.
CREATE TRIGGER inbox_message_added AFTER INSERT ON messages WHEN NOT EXISTS(SELECT 1 FROM inbox_entries WHERE conversation_id=NEW.conversation_id) BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=NEW.conversation_id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL),EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=NEW.conversation_id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
CREATE TRIGGER inbox_message_continued AFTER INSERT ON messages WHEN EXISTS(SELECT 1 FROM inbox_entries WHERE conversation_id=NEW.conversation_id) BEGIN
 UPDATE inbox_entries SET sort_at=(SELECT coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=c.last_message_id),c.updated_at) FROM conversations c WHERE c.id=inbox_entries.conversation_id),contact_revision=(SELECT (SELECT msg.revision FROM messages msg WHERE msg.conversation_id=c.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1) FROM conversations c WHERE c.id=inbox_entries.conversation_id) WHERE conversation_id=NEW.conversation_id;
END;
CREATE TRIGGER inbox_message_removed AFTER DELETE ON messages BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=OLD.conversation_id;
 INSERT INTO inbox_entries(conversation_id,project_id,contact_id,company_id,assigned_to,group_id,status_category,priority,channel,status_id,subject,brand_id,requester_id,submitter_id,submitter_type,created_at,updated_at,ticket_version,sort_at,unresolved,counts_open,ai,ai_profile,snoozed,contact_revision,tags_key) SELECT rc.id,rc.project_id,rc.contact_id,(SELECT cc.company_id FROM contact_companies cc WHERE cc.project_id=rc.project_id AND cc.contact_id=rc.contact_id),rc.assigned_to,rc.group_id,rc.status_category,rc.priority,rc.channel,rc.status_id,rc.subject,rc.brand_id,rc.requester_id,rc.submitter_id,rc.submitter_type,rc.created_at,rc.updated_at,rc.ticket_version,coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=rc.last_message_id),rc.updated_at),rc.resolved_at IS NULL,COALESCE(rc.resolved_at,0)=0,EXISTS(SELECT 1 FROM conversation_ai ca WHERE ca.conversation_id=rc.id AND ca.ai_id IS NOT NULL),EXISTS(SELECT 1 FROM conversation_ai ca JOIN ai_profiles ap ON ap.id=ca.ai_id WHERE ca.conversation_id=rc.id),EXISTS(SELECT 1 FROM workflow_schedules ws WHERE ws.conversation_id=rc.id AND ws.kind='snooze' AND ws.state='pending'),(SELECT msg.revision FROM messages msg WHERE msg.conversation_id=rc.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1),(SELECT json_group_array(ct.tag_id) FROM conversation_tags ct WHERE +ct.project_id=rc.project_id AND ct.conversation_id=rc.id) FROM conversations rc WHERE rc.id=OLD.conversation_id AND (EXISTS(SELECT 1 FROM messages im WHERE im.conversation_id=rc.id) OR EXISTS(SELECT 1 FROM conversation_notes inn WHERE inn.conversation_id=rc.id)) AND NOT EXISTS(SELECT 1 FROM conversation_merges merged WHERE merged.project_id=rc.project_id AND merged.source_id=rc.id AND merged.undone_at IS NULL);
END;
CREATE TRIGGER inbox_message_changed AFTER UPDATE OF id,conversation_id,actor_role,revision,created_at ON messages WHEN NEW.id IS NOT OLD.id OR NEW.conversation_id IS NOT OLD.conversation_id OR NEW.actor_role IS NOT OLD.actor_role OR NEW.revision IS NOT OLD.revision OR NEW.created_at IS NOT OLD.created_at BEGIN
 DELETE FROM inbox_entries WHERE conversation_id=OLD.conversation_id;
