CREATE TRIGGER inbox_message_source_added AFTER INSERT ON move_in_message_sources BEGIN
 UPDATE inbox_entries SET sort_at=(SELECT coalesce((SELECT lm.created_at FROM messages lm WHERE lm.id=c.last_message_id),c.updated_at) FROM conversations c WHERE c.id=inbox_entries.conversation_id),contact_revision=(SELECT (SELECT msg.revision FROM messages msg WHERE msg.conversation_id=c.id AND msg.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM move_in_message_sources ims WHERE ims.message_id=msg.id) ORDER BY msg.revision DESC LIMIT 1) FROM conversations c WHERE c.id=inbox_entries.conversation_id) WHERE conversation_id=(SELECT m.conversation_id FROM messages m WHERE m.id=NEW.message_id);
END;
